/* Dual Heat & Flame Fire Alarm with Arduino Uno */
const int THERMISTOR_PIN = A0;
const int LDR_PIN = A1;
const int BUZZER_PIN = 8;
const int LED_PIN = 13;

// Constants for Steinhart-Hart thermistor calculation
const float SERIES_RESISTOR = 10000.0;
const float NOMINAL_RESISTANCE = 10000.0;
const float NOMINAL_TEMPERATURE = 25.0;
const float B_COEFFICIENT = 3950.0;

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);
  noTone(BUZZER_PIN);
  Serial.println(F("--- Dual Heat & Flame Fire Alarm Initialized ---"));
}

float readTemperatureC() {
  int raw = analogRead(THERMISTOR_PIN);
  if (raw <= 0) raw = 1;
  if (raw >= 1023) raw = 1022;
  float resistance = SERIES_RESISTOR * ((1023.0 / (float)raw) - 1.0);
  float steinhart;
  steinhart = resistance / NOMINAL_RESISTANCE;     // (R/Ro)
  steinhart = log(steinhart);                      // ln(R/Ro)
  steinhart /= B_COEFFICIENT;                      // 1/B * ln(R/Ro)
  steinhart += 1.0 / (NOMINAL_TEMPERATURE + 273.15); // + (1/To)
  steinhart = 1.0 / steinhart;                     // Invert
  steinhart -= 273.15;                             // Convert to Celsius
  return steinhart;
}

void loop() {
  float temperature = readTemperatureC();
  int lightLevel = analogRead(LDR_PIN); // Higher value means brighter light

  Serial.print(F("Temp: "));
  Serial.print(temperature, 1);
  Serial.print(F(" C | Light: "));
  Serial.print(lightLevel);

  // Alarm conditions:
  // 1. Extreme heat alone (> 50 C)
  // 2. High heat (> 38 C) combined with very bright flare/flame (> 750 raw ADC)
  bool alarm = false;
  if (temperature >= 50.0) {
    alarm = true;
    Serial.println(F(" -> ALARM: High Temperature!"));
  } else if (temperature >= 38.0 && lightLevel >= 750) {
    alarm = true;
    Serial.println(F(" -> ALARM: Flame Detected (Heat + Light)!"));
  } else {
    Serial.println(F(" [Normal]"));
  }

  if (alarm) {
    // Pulsing visual and acoustic alarm
    digitalWrite(LED_PIN, HIGH);
    tone(BUZZER_PIN, 2000);
    delay(150);
    digitalWrite(LED_PIN, LOW);
    tone(BUZZER_PIN, 1200);
    delay(150);
  } else {
    digitalWrite(LED_PIN, LOW);
    noTone(BUZZER_PIN);
    delay(400);
  }
}

